# dados_e_fila.tf — as duas tabelas, a fila de entrada e a DLQ de compensacao

# Cada item guarda o proprio saldo E a lista de pedidos que ja reservaram dele.
# E essa lista que sustenta a condicao de idempotencia da secao de codigo.
resource "aws_dynamodb_table" "estoque" {
  name         = "cesta-estoque"
  billing_mode = "PAY_PER_REQUEST" # volume de pedidos varia por dia da semana; sem capacidade fixa a administrar
  hash_key     = "sku"

  attribute {
    name = "sku"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }
}

# pedidoId e a chave; o status muda ao longo da saga e o historico de quem
# escreveu cada status vem do proprio execution history do Step Functions,
# nao duplicado aqui.
resource "aws_dynamodb_table" "pedidos" {
  name         = "cesta-pedidos"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pedidoId"

  attribute {
    name = "pedidoId"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }
}

# Desacopla a criacao do pedido do inicio da saga. Se o Iniciador cair depois
# de consumir mas antes de chamar StartExecution, a visibilidade expira e a
# mensagem volta — e o nome de execucao determinístico evita duplicar a saga.
resource "aws_sqs_queue" "pedidos_criados" {
  name                       = "cesta-pedidos-criados"
  visibility_timeout_seconds = 30
  message_retention_seconds  = 86400
}

# A fila que so existe porque este laboratorio leva a serio que compensacao
# tambem falha. Nao ha redrive automatico dela: quem le esta fila e gente.
resource "aws_sqs_queue" "compensacao_falhou" {
  name                      = "cesta-compensacao-falhou"
  message_retention_seconds = 1209600 # 14 dias — o maximo do SQS, porque o "prazo de resposta" aqui e humano
}

# O alarme e a razao pela qual esta fila nao e um cemiterio silencioso de
# pedidos presos. Sem ele, "REQUER_INTERVENCAO_HUMANA" so e visto por acaso.
resource "aws_cloudwatch_metric_alarm" "compensacao_pendente" {
  alarm_name          = "cesta-saga-compensacao-pendente"
  namespace           = "AWS/SQS"
  metric_name         = "ApproximateNumberOfMessagesVisible"
  statistic           = "Maximum"
  period              = 300
  evaluation_periods  = 1
  threshold           = 0
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    QueueName = aws_sqs_queue.compensacao_falhou.name
  }

  alarm_actions = [aws_sns_topic.alertas_saga.arn]
}

resource "aws_sns_topic" "alertas_saga" {
  name = "cesta-saga-alertas"
}

{
  "Comment": "Cesta - saga do pedido: reservar estoque, cobrar, confirmar - com compensacao por passo",
  "StartAt": "ReservarEstoque",
  "States": {
    "ReservarEstoque": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:111122223333:function:cesta-reservar-estoque",
      "Retry": [
        { "ErrorEquals": ["EstoqueInsuficienteError"], "MaxAttempts": 0 },
        { "ErrorEquals": ["States.TaskFailed"], "IntervalSeconds": 1, "MaxAttempts": 2, "BackoffRate": 2.0 }
      ],
      "Catch": [
        { "ErrorEquals": ["States.ALL"], "ResultPath": "$.erro", "Next": "RegistrarFalhaSemCompensacao" }
      ],
      "Next": "CobrarPagamento"
    },
    "CobrarPagamento": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:111122223333:function:cesta-cobrar-pagamento",
      "Retry": [
        {
          "ErrorEquals": ["GatewayIndisponivelError"],
          "IntervalSeconds": 2,
          "MaxAttempts": 4,
          "BackoffRate": 2.0,
          "MaxDelaySeconds": 15,
          "JitterStrategy": "FULL"
        },
        { "ErrorEquals": ["CartaoRecusadoError"], "MaxAttempts": 0 }
      ],
      "Catch": [
        { "ErrorEquals": ["States.ALL"], "ResultPath": "$.erro", "Next": "LiberarEstoque" }
      ],
      "Next": "ConfirmarPedido"
    },
    "ConfirmarPedido": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:111122223333:function:cesta-confirmar-pedido",
      "Retry": [
        { "ErrorEquals": ["States.TaskFailed"], "IntervalSeconds": 1, "MaxAttempts": 2, "BackoffRate": 2.0 }
      ],
      "Catch": [
        { "ErrorEquals": ["States.ALL"], "ResultPath": "$.erro", "Next": "EstornarPagamento" }
      ],
      "End": true
    },
    "LiberarEstoque": {
      "Comment": "Compensacao alcancada a partir de DOIS caminhos: Catch de CobrarPagamento (direto) e Next de EstornarPagamento (apos estornar). Por isso ela tem de ser idempotente por si so - nada aqui garante uma unica chamada.",
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:111122223333:function:cesta-liberar-estoque",
      "Retry": [
        {
          "ErrorEquals": ["States.TaskFailed"],
          "IntervalSeconds": 2,
          "MaxAttempts": 3,
          "BackoffRate": 2.0,
          "JitterStrategy": "FULL"
        }
      ],
      "Catch": [
        { "ErrorEquals": ["States.ALL"], "ResultPath": "$.erroCompensacao", "Next": "CompensacaoFalhouParaFilaHumana" }
      ],
      "Next": "RegistrarFalhaComEstoqueLiberado"
    },
    "EstornarPagamento": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:111122223333:function:cesta-estornar-pagamento",
      "Retry": [
        {
          "ErrorEquals": ["GatewayIndisponivelError"],
          "IntervalSeconds": 2,
          "MaxAttempts": 4,
          "BackoffRate": 2.0,
          "MaxDelaySeconds": 15,
          "JitterStrategy": "FULL"
        }
      ],
      "Catch": [
        { "ErrorEquals": ["States.ALL"], "ResultPath": "$.erroCompensacao", "Next": "CompensacaoFalhouParaFilaHumana" }
      ],
      "Next": "LiberarEstoque"
    },
    "RegistrarFalhaSemCompensacao": {
      "Type": "Task",
      "Resource": "arn:aws:states:::dynamodb:putItem",
      "Parameters": {
        "TableName": "cesta-pedidos",
        "Item": {
          "pedidoId": { "S.$": "$.pedidoId" },
          "status": { "S": "FALHOU_SEM_RESERVA" },
          "motivo": { "S.$": "$.erro.Cause" }
        }
      },
      "End": true
    },
    "RegistrarFalhaComEstoqueLiberado": {
      "Type": "Task",
      "Resource": "arn:aws:states:::dynamodb:putItem",
      "Parameters": {
        "TableName": "cesta-pedidos",
        "Item": {
          "pedidoId": { "S.$": "$.pedidoId" },
          "status": { "S": "FALHOU_COMPENSADO" },
          "motivo": { "S.$": "$.erro.Cause" }
        }
      },
      "End": true
    },
    "CompensacaoFalhouParaFilaHumana": {
      "Comment": "Aqui a saga desiste de se resolver sozinha. A mensagem carrega o pedidoId, o passo que falhou e o motivo da falha da PROPRIA compensacao.",
      "Type": "Task",
      "Resource": "arn:aws:states:::sqs:sendMessage",
      "Parameters": {
        "QueueUrl": "https://sqs.us-east-1.amazonaws.com/111122223333/cesta-compensacao-falhou",
        "MessageBody": {
          "pedidoId.$": "$.pedidoId",
          "erroOriginal.$": "$.erro",
          "erroDaCompensacao.$": "$.erroCompensacao"
        }
      },
      "Next": "RegistrarRequerIntervencaoHumana"
    },
    "RegistrarRequerIntervencaoHumana": {
      "Type": "Task",
      "Resource": "arn:aws:states:::dynamodb:putItem",
      "Parameters": {
        "TableName": "cesta-pedidos",
        "Item": {
          "pedidoId": { "S.$": "$.pedidoId" },
          "status": { "S": "REQUER_INTERVENCAO_HUMANA" }
        }
      },
      "End": true
    }
  }
}

# saga.tf — a maquina de estados e o papel minimo para rodar as Tasks

resource "aws_cloudwatch_log_group" "saga_pedido" {
  name              = "/aws/vendedlogs/states/cesta-saga-pedido"
  retention_in_days = 30
}

resource "aws_sfn_state_machine" "saga_pedido" {
  name     = "cesta-saga-pedido"
  role_arn = aws_iam_role.saga_pedido.arn
  type     = "STANDARD" # nao Express: a cobranca nao e idempotente por padrao no gateway,
                         # e Standard garante exactly-once por Task (ver a secao de decisoes)

  definition = file("${path.module}/asl/saga-pedido.json")

  # Sem isto, um pedido preso vira mistério: nenhum log fica alem do que a
  # propria Lambda escreve. Com ALL, todo Retry e todo Catch fica no rastro.
  logging_configuration {
    log_destination        = "${aws_cloudwatch_log_group.saga_pedido.arn}:*"
    include_execution_data = true
    level                   = "ALL"
  }
}

# O papel da MAQUINA, nao das Lambdas: ela so precisa invocar as seis funcoes
# e escrever nas duas tabelas via integracao direta de servico (RegistrarFalha*).
data "aws_iam_policy_document" "saga_pedido_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "saga_pedido" {
  name               = "cesta-saga-pedido-role"
  assume_role_policy = data.aws_iam_policy_document.saga_pedido_assume.json
}

# Recurso especifico por Lambda, nunca "lambda:InvokeFunction" com "*" — a
# maquina so pode chamar as SEIS funcoes que ela de fato orquestra.
data "aws_iam_policy_document" "saga_pedido_permissoes" {
  statement {
    effect = "Allow"
    actions = ["lambda:InvokeFunction"]
    resources = [
      aws_lambda_function.reservar_estoque.arn,
      aws_lambda_function.cobrar_pagamento.arn,
      aws_lambda_function.confirmar_pedido.arn,
      aws_lambda_function.liberar_estoque.arn,
      aws_lambda_function.estornar_pagamento.arn,
    ]
  }

  statement {
    effect    = "Allow"
    actions   = ["dynamodb:PutItem"]
    resources = [aws_dynamodb_table.pedidos.arn]
  }

  statement {
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.compensacao_falhou.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogDelivery", "logs:GetLogDelivery", "logs:UpdateLogDelivery",
      "logs:DeleteLogDelivery", "logs:ListLogDeliveries", "logs:PutResourcePolicy",
      "logs:DescribeResourcePolicies", "logs:DescribeLogGroups",
    ]
    # As acoes de log delivery do Step Functions nao aceitam recurso especifico —
    # e uma limitacao documentada da integracao com CloudWatch Logs, nao preguica.
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "saga_pedido_permissoes" {
  role   = aws_iam_role.saga_pedido.id
  policy = data.aws_iam_policy_document.saga_pedido_permissoes.json
}

// ReservarEstoqueFunction.cs — a condição é a idempotência, não um try/catch

public class ReservarEstoqueFunction
{
    private readonly IAmazonDynamoDB _dynamo;

    public async Task<object> FunctionHandler(SagaInput evento, ILambdaContext ctx)
    {
        try
        {
            // A condição faz duas coisas ao mesmo tempo: garante saldo suficiente
            // E garante que ESTE pedidoId ainda não está na lista de reservas do
            // item. Um retry do Step Functions chama esta função de novo com o
            // MESMO input — sem a segunda parte da condição, a segunda chamada
            // reservaria uma unidade extra que ninguém pediu.
            await _dynamo.UpdateItemAsync(new UpdateItemRequest
            {
                TableName = "cesta-estoque",
                Key = new() { ["sku"] = new AttributeValue { S = evento.Sku } },
                UpdateExpression = "SET saldo = saldo - :qtd, reservas.#pedido = :qtd",
                ConditionExpression = "saldo >= :qtd AND attribute_not_exists(reservas.#pedido)",
                ExpressionAttributeNames = new() { ["#pedido"] = evento.PedidoId },
                ExpressionAttributeValues = new()
                {
                    [":qtd"] = new AttributeValue { N = evento.Quantidade.ToString() },
                },
            });

            return new { evento.PedidoId, evento.Sku, evento.Quantidade, evento.ValorCentavos };
        }
        catch (ConditionalCheckFailedException) when (await JaReservadoParaEstePedido(evento))
        {
            // A CONDIÇÃO falhou porque a reserva JÁ EXISTE para este pedidoId —
            // não porque o saldo é insuficiente. Isto é o retry chegando de novo,
            // não um erro: devolvemos sucesso sem reservar nada a mais.
            return new { evento.PedidoId, evento.Sku, evento.Quantidade, evento.ValorCentavos };
        }
        catch (ConditionalCheckFailedException)
        {
            // Aqui sim é o caso definitivo: saldo insuficiente. Nomear o erro
            // como tal permite ao ASL configurar MaxAttempts=0 para ele — repetir
            // uma reserva impossível não a torna possível.
            throw new EstoqueInsuficienteError($"sem saldo para {evento.Sku}");
        }
    }

    private async Task<bool> JaReservadoParaEstePedido(SagaInput evento)
    {
        var item = await _dynamo.GetItemAsync(new GetItemRequest
        {
            TableName = "cesta-estoque",
            Key = new() { ["sku"] = new AttributeValue { S = evento.Sku } },
        });
        return item.Item.TryGetValue("reservas", out var reservas)
            && reservas.M.ContainsKey(evento.PedidoId);
    }
}

// CobrarPagamentoFunction.cs — dois erros com nomes diferentes, para o ASL decidir sozinho

public class CobrarPagamentoFunction
{
    private readonly IGatewayPagamento _gateway;

    public async Task<object> FunctionHandler(SagaInput evento, ILambdaContext ctx)
    {
        try
        {
            // O token de idempotência é derivado do pedidoId, não gerado a cada
            // chamada. Hipótese declarada deste laboratório: o gateway aceita um
            // cabeçalho de idempotência e devolve o MESMO resultado para o MESMO
            // token por 24h — como a maioria dos gateways reais faz. Sem isso, o
            // Retry desta Task cobraria o cliente uma vez por tentativa.
            var resultado = await _gateway.CobrarAsync(
                token: $"cesta-cobranca-{evento.PedidoId}",
                cartao: evento.CartaoToken,
                valorCentavos: evento.ValorCentavos);

            if (resultado.Recusado)
                // Erro DEFINITIVO: cartão recusado não muda de resposta em uma
                // segunda tentativa. O ASL marca MaxAttempts=0 para este nome.
                throw new CartaoRecusadoError(evento.PedidoId);

            return new { evento.PedidoId, resultado.IdTransacao };
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            // Erro TRANSITÓRIO: rede, timeout, gateway fora do ar. O ASL faz
            // Retry com backoff e jitter para este nome — jitter porque, se
            // muitos pedidos cobrarem ao mesmo tempo, retries sincronizados
            // martelariam o gateway exatamente enquanto ele se recupera.
            throw new GatewayIndisponivelError(evento.PedidoId);
        }
    }
}

// LiberarEstoqueFunction.cs — compensação chamada de DOIS caminhos; idempotente por si só

public class LiberarEstoqueFunction
{
    private readonly IAmazonDynamoDB _dynamo;

    public async Task<object> FunctionHandler(SagaInput evento, ILambdaContext ctx)
    {
        // No ASL, este mesmo estado é o Next tanto do Catch de CobrarPagamento
        // quanto do Next de EstornarPagamento. Nada no grafo impede que, num
        // reprocessamento raro, ele seja alcançado mais de uma vez para o MESMO
        // pedido — por isso a condição abaixo, e não um UpdateItem incondicional.
        try
        {
            await _dynamo.UpdateItemAsync(new UpdateItemRequest
            {
                TableName = "cesta-estoque",
                Key = new() { ["sku"] = new AttributeValue { S = evento.Sku } },
                UpdateExpression = "SET saldo = saldo + :qtd REMOVE reservas.#pedido",
                // Só libera se a reserva deste pedido AINDA existir. Chamar de
                // novo depois de já ter liberado não soma saldo a mais — a
                // condição falha, e tratamos isso como sucesso silencioso.
                ConditionExpression = "attribute_exists(reservas.#pedido)",
                ExpressionAttributeNames = new() { ["#pedido"] = evento.PedidoId },
                ExpressionAttributeValues = new()
                {
                    [":qtd"] = new AttributeValue { N = evento.Quantidade.ToString() },
                },
            });
        }
        catch (ConditionalCheckFailedException)
        {
            // Já liberado por uma chamada anterior (o outro caminho do grafo, ou
            // um retry). Não é falha: é a idempotência funcionando como desenhada.
        }

        return new { evento.PedidoId, Liberado = true };
    }
}
